import * as React from "react"

import {
  Collapsible,
  CollapsiblePanel,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"

import { ChevronDownIcon, Trash2Icon } from "lucide-react"

import { Button } from "@/components/ui/button"



function CollapsibleControlledPreview() {
  const [open, setOpen] = React.useState(false)

  return (
    <div className="flex w-full max-w-sm flex-col gap-3">
      <Collapsible
        className="rounded-lg border border-border"
        open={open}
        onOpenChange={setOpen}
      >
        <CollapsibleTrigger className="flex w-full items-center justify-between gap-3 px-4 py-3.5 text-left font-medium text-sm">
          {open ? "Hide" : "Show"} details
          <ChevronDownIcon className="size-4 shrink-0 text-muted-foreground transition-transform duration-200" />
        </CollapsibleTrigger>
        <CollapsiblePanel>
          <div className="px-4 pb-4 text-sm text-muted-foreground">
            This collapsible is controlled externally. Current state:{" "}
            <code className="rounded bg-muted px-1.5 py-0.5 font-mono text-xs text-foreground">
              {String(open)}
            </code>
          </div>
        </CollapsiblePanel>
      </Collapsible>
      <Button
        onClick={() => setOpen((value) => !value)}
        size="sm"
        variant="outline"
      >
        Toggle externally
      </Button>
    </div>
  )
}

combobox-multi-select-overflow:
import * as React from "react"

import {
  Combobox,
  ComboboxChip,
  ComboboxChips,
  ComboboxTrigger,
  ComboboxChipsInput,
  ComboboxContent,
  ComboboxEmpty,
  ComboboxGroup,
  ComboboxInput,
  ComboboxItem,
  ComboboxLabel,
  ComboboxList,
  ComboboxSeparator,
  ComboboxValue,
  useComboboxAnchor,
} from "@/components/ui/combobox"

import { SearchIcon } from "lucide-react"



const issueLabels = [
  "bug",
  "enhancement",
  "documentation",
  "good first issue",
  "help wanted",
  "invalid",
  "question",
  "wontfix",
  "duplicate",
  "security",
  "performance",
  "breaking change",
]

function ComboboxMultiSelectOverflowPreview() {
  const MAX_CHIPS = 2
  const [selected, setSelected] = React.useState<string[]>([
    "bug",
    "enhancement",
    "documentation",
    "security",
  ])
  const [expanded, setExpanded] = React.useState(false)
  const anchor = useComboboxAnchor()

  return (
    <div className="w-full max-w-md flex items-center justify-center">
      <div ref={anchor} className="w-full">
        <Combobox
          multiple
          items={issueLabels}
          value={selected}
          onValueChange={(val) => setSelected(Array.isArray(val) ? val : [])}
        >
          <ComboboxValue>
            {(selectedItems: string[]) => {
              const overflow = Math.max(0, selectedItems.length - MAX_CHIPS)
              const visible =
                expanded || overflow === 0 ? selectedItems : selectedItems.slice(0, MAX_CHIPS)
              return (
                <ComboboxChips startAddon={<SearchIcon />}>
                  {visible.map((item) => (
                    <ComboboxChip key={item}>{item}</ComboboxChip>
                  ))}
                  {!expanded && overflow > 0 && (
                    <span
                      role="button"
                      tabIndex={0}
                      className="inline-flex h-[calc(--spacing(5.5))] cursor-pointer items-center rounded-md bg-muted-foreground/10 px-2 text-xs font-medium hover:bg-muted-foreground/20"
                      onMouseDown={(e) => {
                        e.preventDefault()
                        e.stopPropagation()
                        setExpanded(true)
                      }}
                      onKeyDown={(e) => {
                        if (e.key === "Enter" || e.key === " ") {
                          e.preventDefault()
                          setExpanded(true)
                        }
                      }}
                    >
                      +{overflow} more
                    </span>
                  )}
                  {expanded && overflow > 0 && (
                    <span
                      role="button"
                      tabIndex={0}
                      className="inline-flex h-[calc(--spacing(5.5))] cursor-pointer items-center rounded-md px-2 text-xs text-muted-foreground hover:text-foreground"
                      onMouseDown={(e) => {
                        e.preventDefault()
                        e.stopPropagation()
                        setExpanded(false)
                      }}
                      onKeyDown={(e) => {
