                    >
                      Show less
                    </span>
                  )}
                  <ComboboxChipsInput placeholder="" />
                </ComboboxChips>
              )
            }}
          </ComboboxValue>
          <ComboboxContent anchor={anchor}>
            <ComboboxEmpty>No labels found.</ComboboxEmpty>
            <ComboboxList className="max-h-none">
