import * as React from "react"

import {
  Combobox,
  ComboboxChip,
  ComboboxChips,
  ComboboxTrigger,
  ComboboxChipsInput,
  ComboboxContent,
  ComboboxEmpty,
  ComboboxGroup,
  ComboboxInput,
  ComboboxItem,
  ComboboxLabel,
  ComboboxList,
  ComboboxSeparator,
  ComboboxValue,
  useComboboxAnchor,
} from "@/components/ui/combobox"

import { Spinner } from "@/components/ui/spinner"



const teammates = [
  "Alice Johnson",
  "Bob Martinez",
  "Carol White",
  "David Chen",
  "Eva Rodriguez",
  "Frank Kim",
  "Grace Lee",
  "Henry Patel",
  "Isla Scott",
  "James Walker",
]

function ComboboxAsyncPreview() {
  const [inputValue, setInputValue] = React.useState("")
  const [isLoading, setIsLoading] = React.useState(false)
  const [results, setResults] = React.useState(teammates.slice(0, 6))

  React.useEffect(() => {
    setIsLoading(true)
    const timer = window.setTimeout(() => {
      const q = inputValue.trim().toLowerCase()
      setResults(q ? teammates.filter((t) => t.toLowerCase().includes(q)) : teammates.slice(0, 6))
      setIsLoading(false)
    }, 300)
    return () => window.clearTimeout(timer)
  }, [inputValue])

  return (
    <div className="w-full max-w-md flex items-center justify-center">
      <Combobox items={results} inputValue={inputValue} onInputValueChange={setInputValue}>
        <ComboboxInput
          placeholder="Assign to teammate..."
          showClear={!!inputValue}
          showTrigger={!inputValue}
        />
        <ComboboxContent>
          <div className="flex items-center gap-2 border-b border-border px-3 py-2 text-xs text-muted-foreground">
            {isLoading && <Spinner className="size-3" />}
            {isLoading
              ? "Searching..."
              : `${results.length} teammate${results.length === 1 ? "" : "s"}`}
          </div>
          <ComboboxEmpty>No teammates found.</ComboboxEmpty>
          <ComboboxList>
            {(item) => (
              <ComboboxItem key={item} value={item}>
                {item}
              </ComboboxItem>
            )}
          </ComboboxList>
        </ComboboxContent>
      </Combobox>
    </div>
  )
}

