  const {
    rows,
    setRows,
    total,
    rowPinning,
    setRowPinning,
    columnPreferences,
    isLoading,
    error,
    refresh,
    reportError,
    clearError,
  } = sourceData

  const handleRowPinningChange = useCallback(
    (updater: Parameters<typeof setRowPinning>[0]) => {
