        accessorKey: "team",
        id: "team",
        header: ({ column }) => (
          <DataGridColumnHeader
            title="Team"
            column={column}
            filterType={features.excelFilters ? "text" : undefined}
          />
        ),
        enablePinning: true,
        filterFn: createExcelFilterFn<StaffMember>(),
        meta: {
          headerTitle: "Team",
          editor: {
            kind: "select",
            label: "Team",
            options: [
              { label: "Design", value: "Design" },
              { label: "Engineering", value: "Engineering" },
              { label: "Operations", value: "Operations" },
              { label: "Product", value: "Product" },
            ],
            inlineOnly: true,
            renderInline: createInlineRenderer("select"),
          },
        },
        cell: ({ cell }) => <EditableFeatureCell cell={cell} enabled={features.inlineEditing} />,
      },
      {
        accessorKey: "title",
        id: "title",
        header: ({ column }) => (
          <DataGridColumnHeader
            title="Title"
            column={column}
            filterType={features.excelFilters ? "text" : undefined}
          />
        ),
        enablePinning: true,
        filterFn: createExcelFilterFn<StaffMember>(),
        meta: {
          headerTitle: "Title",
          editor: {
            kind: "text",
            label: "Title",
            required: true,
            inlineOnly: true,
            renderInline: createInlineRenderer("text"),
          },
        },
        cell: ({ cell }) => <EditableFeatureCell cell={cell} enabled={features.inlineEditing} />,
      },
      {
        accessorKey: "salary",
        id: "salary",
        header: ({ column }) => (
          <DataGridColumnHeader
            title="Salary"
            column={column}
            filterType={features.excelFilters ? "number" : undefined}
          />
        ),
        enablePinning: true,
        filterFn: createExcelFilterFn<StaffMember>(),
        meta: {
          headerTitle: "Salary",
          editor: {
            kind: "number",
            label: "Salary",
            min: 0,
            step: 1000,
            inlineOnly: true,
            renderInline: createInlineRenderer("number"),
