export function PatternEdit1() {
  const { add } = useToast()
  const [data, setData] = useState<TeamMember[]>(initialData)
  const [pagination, setPagination] = useState<PaginationState>({
    pageIndex: 0,
    pageSize: 5,
  })
  const [sorting, setSorting] = useState<SortingState>([{ id: "name", desc: false }])
  const [columnVisibility, setColumnVisibility] = useState<ColumnVisibilityState>({
    notes: false,
  })

  const handleRestoreRow = useCallback(
    (rowId: string) => {
      setData((currentData) => restoreSnapshot(rowId, currentData))
      add({
        title: "Row restored",
        description: "The original snapshot was restored for this teammate.",
        type: "success",
      })
    },
    [add]
  )

  const handleResetAll = useCallback(() => {
    setData(initialData)
    add({
      title: "Grid reset",
      description: "Every inline change has been restored to the initial sample data.",
      type: "success",
    })
  }, [add])

  const columns = useMemo<DataGridColumnDef<TeamMember>[]>(
    () => [
      {
        accessorKey: "name",
        id: "name",
        header: ({ column }) => <DataGridColumnHeader title="Name" column={column} />,
        cell: ({ cell }) => <DataGridEditableCell cell={cell} />,
