            kind: "email",
            label: "Email",
            placeholder: "name@company.com",
            required: true,
            validate: validateEmail,
          },
        },
      },
      {
        accessorKey: "role",
        id: "role",
        header: ({ column }) => <DataGridColumnHeader title="Role" column={column} />,
        cell: ({ cell }) => <DataGridEditableCell cell={cell} />,
        size: 180,
        meta: {
          skeleton: cellSkeletons.role,
          editor: {
            kind: "select",
            label: "Role",
            options: roleOptions,
            required: true,
          },
        },
      },
      {
        accessorKey: "workMode",
        id: "workMode",
        header: ({ column }) => <DataGridColumnHeader title="Work Mode" column={column} />,
        cell: ({ cell }) => <DataGridEditableCell cell={cell} />,
        size: 240,
        enableSorting: false,
        meta: {
          skeleton: cellSkeletons.workMode,
          editor: {
            kind: "radio",
            label: "Work Mode",
            options: workModeOptions,
            required: true,
          },
        },
      },
      {
        accessorKey: "salary",
        id: "salary",
        header: ({ column }) => <DataGridColumnHeader title="Salary" column={column} />,
        cell: ({ cell }) => <DataGridEditableCell cell={cell} />,
        size: 170,
        meta: {
          skeleton: cellSkeletons.salary,
          editor: {
            kind: "number",
            label: "Salary",
            min: 60000,
            max: 250000,
            step: 1000,
            required: true,
          },
        },
      },
      {
        accessorKey: "mentor",
        id: "mentor",
        header: ({ column }) => <DataGridColumnHeader title="Mentor" column={column} />,
        cell: ({ cell }) => <DataGridEditableCell cell={cell} />,
        size: 110,
        enableSorting: false,
        meta: {
          skeleton: cellSkeletons.toggle,
          editor: {
            kind: "checkbox",
            label: "Mentor",
            description: "Mark whether this teammate is available for contributor pairing.",
          },
        },
      },
      {
        accessorKey: "active",
        id: "active",
        header: ({ column }) => <DataGridColumnHeader title="Active" column={column} />,
        cell: ({ cell }) => <DataGridEditableCell cell={cell} />,
        size: 110,
        meta: {
          skeleton: cellSkeletons.toggle,
          editor: {
            kind: "switch",
            label: "Active",
            description: "Controls whether the teammate is currently active in the rotation.",
          },
        },
      },
      {
        accessorKey: "rating",
        id: "rating",
        header: ({ column }) => <DataGridColumnHeader title="Quality" column={column} />,
        cell: ({ cell }) => <DataGridEditableCell cell={cell} />,
        size: 150,
        meta: {
          skeleton: cellSkeletons.rating,
          editor: {
            kind: "rating",
            label: "Quality score",
            description: "A quick internal confidence score for demo readiness.",
          },
        },
      },
      {
        accessorKey: "notes",
        id: "notes",
        header: ({ column }) => <DataGridColumnHeader title="Notes" column={column} />,
        cell: ({ cell }) => <DataGridEditableCell cell={cell} />,
        size: 260,
        enableSorting: false,
        meta: {
          skeleton: cellSkeletons.notes,
          editor: {
            kind: "textarea",
            label: "Notes",
            description:
              "This field is hidden from the table but generated automatically inside the edit dialog.",
            placeholder: "Document extra context for the row here.",
            dialogOnly: true,
          },
        },
      },
      {
        id: "actions",
        header: "",
        cell: ({ row, table }) => (
          <ActionsCell row={row} table={table} onRestoreRow={handleRestoreRow} />
        ),
        size: 60,
        enableSorting: false,
        enableHiding: false,
        enableResizing: false,
        meta: {
          skeleton: cellSkeletons.actions,
        },
      },
    ],
    [handleRestoreRow]
  )

  const editorColumns = useMemo(
    () =>
      columns.reduce<EditableDataGridColumn<TeamMember>[]>((accumulator, column) => {
        if (column.id && column.meta?.editor) {
          accumulator.push({
            id: String(column.id),
            editor: column.meta.editor as DataGridColumnEditor<TeamMember, unknown>,
          })
        }

        return accumulator
      }, []),
    [columns]
  )

  const editing = useEditableDataGrid<TeamMember>({
    data,
    setData,
    getRowId: (row) => row.id,
    editorColumns,
    onSaveRow: ({ nextRow }) => {
      add({
        title: "Dialog changes applied",
        description: `${nextRow.name} has been updated from the generated form.`,
        type: "success",
      })
      return nextRow
    },
    onError: (_error, context) => {
      add({
        title: "Update failed",
        description: context.message,
        type: "error",
      })
    },
  })

  const table = useTable({
    features: dataGridFeatures,
    data,
    columns,
    pageCount: Math.ceil(data.length / pagination.pageSize),
    getRowId: (row) => row.id,
    state: {
      pagination,
      sorting,
      columnVisibility,
    },
    meta: {
      editing,
    },
    columnResizeMode: "onChange",
    onPaginationChange: setPagination,
    onSortingChange: setSorting,
    onColumnVisibilityChange: setColumnVisibility,
  })

  return (
    <DataGrid
      table={table}
      recordCount={data.length}
      tableLayout={{
        columnsResizable: true,
        headerSticky: true,
      }}
      tableClassNames={{
        headerSticky: "sticky top-0 z-10 bg-background/90 backdrop-blur-xs",
      }}
    >
      <Card variant="elevated" className="w-full gap-0 p-0">
        <CardHeader className="flex items-center justify-between gap-3 px-4 py-3">
          <div className="flex items-center gap-2">
            <span className="text-foreground text-sm font-medium">Team Editing Sandbox</span>
            <Badge variant="info-outline" size="sm">
              Inline + Dialog
            </Badge>
          </div>
          <div className="flex items-center gap-2">
            <Button variant="destructive-outline" size="xs" onClick={handleResetAll}>
              <RotateCcwIcon className="size-3" />
              Reset all
            </Button>
          </div>
        </CardHeader>
        <CardContent className="border-y p-0">
          <DataGridScrollArea className="h-[460px]">
            <DataGridTable />
          </DataGridScrollArea>
        </CardContent>
        <CardFooter className="border-none bg-transparent! px-4 py-3">
          <DataGridPagination />
        </CardFooter>
      </Card>

      <DataGridEditDialog
        table={table}
        title="Edit teammate"
        description="This dialog is generated from the same column metadata that powers inline editing."
      />
    </DataGrid>
  )
}

const DataGridEditingPreview = PatternEdit1

function DataGridEditingToastPreview() {
  return (
    <ToastProvider>
      <DataGridEditingPreview />
    </ToastProvider>
  )
}

