import { ToastProvider, useToast } from "@/components/ui/toast"

import * as React from "react"

import { Form } from "@/components/ui/form"

import {
  TimePicker,
  TimePickerDialog,
  TimePickerInput,
  formatTimeValue,
} from "@/components/ui/time-picker"

import { Button } from "@/components/ui/button"



function TimePickerFormPreviewContent() {
  const [value, setValue] = React.useState<string | null>(null)
  const [error, setError] = React.useState("")
  const toast = useToast()

  return (
    <Form
      className="w-full max-w-sm"
      onFormSubmit={async () => {
        if (!value) {
          setError("Select a meeting time.")
          return
        }

        setError("")
        toast.add({
          title: "Time submitted",
          description: `${formatTimeValue(value, { formatPreset: "medium" })} (${value})`,
          type: "success",
          timeout: 4000,
        })
      }}
    >
      <TimePickerInput
        label="Meeting time"
        value={value}
        onValueChange={(nextValue) => {
          setValue(nextValue)
          if (nextValue) setError("")
        }}
        defaultPickerValue="09:30"
        minuteStep={5}
      />
      <input type="hidden" name="meetingTime" value={value ?? ""} />
      {error ? (
        <p role="alert" className="text-destructive-foreground text-xs">
          {error}
        </p>
      ) : null}
      <Button type="submit">Submit time</Button>
    </Form>
  )
}

function TimePickerFormPreview() {
  return (
    <ToastProvider>
      <TimePickerFormPreviewContent />
    </ToastProvider>
  )
}

